K, W, C = 'Knowledge', 'Wisdom', 'Command'
S, R = 'stated', 'reflection'
def ins(t, b, text): return {'type': t, 'basis': b, 'text': text}
def keeps(t): return {'dir': 'keeps', 'text': t}
def loses(t): return {'dir': 'loses', 'text': t}
def between(t): return {'dir': 'between', 'text': t}
AGREE = between("Hebrew, Greek, Latin and King James agree in substance; only the rendering of the divine name and small turns of phrase differ.")
FORMULA = [between("The Latin, Greek and King James all have the speech formula; the divine name is rendered 'the Lord' outside the Hebrew.")]
TENT = [loses("Hebrew 'Tent of Meeting' is lost."), keeps("Greek 'Tent of Testimony'."), between("The Latin has 'tabernacle of the covenant'; the King James 'tabernacle of the congregation'.")]
AGE = [loses("Hebrew 'from thirty years old' is lost."), keeps("Greek 'from twenty-five years old', agreeing with 8:24."), between("The Latin and King James have thirty.")]
TAHASH = [loses("Hebrew 'tahash skin', an uncertain material, is lost."), keeps("Greek 'blue skin' or 'blue leather'."), between("The Latin has 'violet skins'; the King James 'badgers' skins'.")]
CLAN = [loses("Hebrew 'clans' is lost."), keeps("Greek 'divisions'."), between("The Latin and King James have 'families'.")]
MOUTH = [loses("Hebrew 'at the mouth of YHWH' is lost."), keeps("Greek 'by the voice of the Lord'."), between("The Latin and King James have 'word' or 'commandment of the Lord'.")]
FRAME = [between("The carrying frame or bar (Hebrew mot) is the Greek's 'carrying poles'; the Latin and King James 'bar' or 'staves'.")]

def v(received, explain, shared, k, w, lost, entries=None, cmd=None):
    inst = [ins(K, S, k)]
    if cmd: inst.append(ins(C, S, cmd))
    inst.append(ins(W, R, w))
    return {'received': received, 'explain': explain, 'shared': shared, 'instructions': inst, 'entries': entries if entries is not None else [], 'lost': lost}

def age(ref, who):
    return v(f"From thirty years old to fifty, everyone entering the service for work in the Tent of Meeting.", "The Hebrew thirty; the Greek twenty-five, agreeing with 8:24. The difference changes eligibility.",
      ["Thirty to fifty.", "Entering the service.", "In the tent."], f"{who} served from thirty to fifty.", "Thirty or twenty-five: the Hebrew has two ages for the Levites' start, here and in chapter 8, and the Greek chose one of them.", AGE + TENT)

